package com.ecole.gestion_scolaire.hr.entity; import com.ecole.gestion_scolaire.hr.enums.DocumentStatus; import jakarta.persistence.*; import java.time.*; @Entity @Table(name="employee_admin_document") public class EmployeeAdminDocument { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="employee_id") private Employee employee; @Column(name="document_type",nullable=false,length=80) private String documentType; @Column(name="document_number",length=100) private String documentNumber; @Column(name="issued_on") private LocalDate issuedOn; @Column(name="expires_on") private LocalDate expiresOn; @Column(name="file_reference",length=500) private String fileReference; @Enumerated(EnumType.STRING) @Column(nullable=false,length=30) private DocumentStatus status; @Column(columnDefinition="TEXT") private String notes; public Long getId(){return id;} public Employee getEmployee(){return employee;} public void setEmployee(Employee v){employee=v;} public String getDocumentType(){return documentType;} public void setDocumentType(String v){documentType=v;} public String getDocumentNumber(){return documentNumber;} public void setDocumentNumber(String v){documentNumber=v;} public LocalDate getIssuedOn(){return issuedOn;} public void setIssuedOn(LocalDate v){issuedOn=v;} public LocalDate getExpiresOn(){return expiresOn;} public void setExpiresOn(LocalDate v){expiresOn=v;} public String getFileReference(){return fileReference;} public void setFileReference(String v){fileReference=v;} public DocumentStatus getStatus(){return status;} public void setStatus(DocumentStatus v){status=v;} public String getNotes(){return notes;} public void setNotes(String v){notes=v;} }